// @FIGURE_CODE_BEGIN
var UC_RED = '#e8000d', UC_BLK = '#000', UC_BLUE = '#1565c0', UC_GREEN = '#2e9b3f',
  UC_ACC = '#ff9800', UC_SIB = '#9c27b0';
