var UCW = 860, UCH = 610, cx = 432, cy = 297, Rr = 218, FS = 19;

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, UCW, UCH);

var gMeas = draw.group().attr('opacity', 0);
var gBase = draw.group(), gOverlay = draw.group(), gHover = draw.group(),
  gLabels = draw.group(), gRead = draw.group(), gHit = draw.group();

var UCPTS = [
  { d: 0, r: { t: '0' }, c: ['1', '0'] },
  { d: 30, r: { n: 'π', dn: '6' }, c: ['s3', '1/2'] },
  { d: 45, r: { n: 'π', dn: '4' }, c: ['s2', 's2'] },
  { d: 60, r: { n: 'π', dn: '3' }, c: ['1/2', 's3'] },
  { d: 90, r: { n: 'π', dn: '2' }, c: ['0', '1'] },
  { d: 120, r: { n: '2π', dn: '3' }, c: ['-1/2', 's3'] },
  { d: 135, r: { n: '3π', dn: '4' }, c: ['-s2', 's2'] },
  { d: 150, r: { n: '5π', dn: '6' }, c: ['-s3', '1/2'] },
  { d: 180, r: { t: 'π' }, c: ['-1', '0'] },
  { d: 210, r: { n: '7π', dn: '6' }, c: ['-s3', '-1/2'] },
  { d: 225, r: { n: '5π', dn: '4' }, c: ['-s2', '-s2'] },
  { d: 240, r: { n: '4π', dn: '3' }, c: ['-1/2', '-s3'] },
  { d: 270, r: { n: '3π', dn: '2' }, c: ['0', '-1'] },
  { d: 300, r: { n: '5π', dn: '3' }, c: ['1/2', '-s3'] },
  { d: 315, r: { n: '7π', dn: '4' }, c: ['s2', '-s2'] },
  { d: 330, r: { n: '11π', dn: '6' }, c: ['s3', '-1/2'] }
