var UC_R360 = { t: '2π' };

function ptXY(deg) {
  var a = deg * Math.PI / 180;
  return [cx + Rr * Math.cos(a), cy - Rr * Math.sin(a)];
}
function mkText(g, s) { return g.plain ? g.plain(s) : g.text(s); }
function textW(s, size) {
