  var BAR = -Math.round(fs * 0.30);
  var nBase = BAR - Math.round(nf * 0.20);
  var dBase = BAR + Math.round(nf * 0.95);
  var n = mkText(g, num).font({ family: UC_FAM, size: nf }).fill(fill).attr({ x: 0, y: nBase });
  var d = mkText(g, den).font({ family: UC_FAM, size: nf }).fill(fill).attr({ x: 0, y: dBase });
  var wn = n.bbox().width, wd = d.bbox().width, w = Math.max(wn, wd) + 5;
  var nx = x + (w - wn) / 2;
