  g.line(x + 1, BAR, x + w - 1, BAR).stroke({ color: fill, width: 1.3 });
  if (num.charAt(0) === '\u221A') {
    var wr = textW('\u221A', nf);
    g.line(nx + wr * 0.90, nBase - nf * 0.78, nx + wn, nBase - nf * 0.78)
      .stroke({ color: fill, width: 1.1 });
