}
function buildRow(items, fs) {
  var g = gLabels.group(), x = 0;
  items.forEach(function (it) {
    if (it.gap) { x += it.gap; return; }
    if (it.f) { x += addFrac(g, x, it.n, it.d, it.fill || UC_BLK, fs) + 1; return; }
    var t = mkText(g, it.t).font({ family: UC_FAM, size: it.size || fs })
