  out.push({ t: ',', fill: fill }); out.push({ gap: 5 });
  out = out.concat(compItems(c[1], fill));
  out.push({ gap: 2 }); out.push({ t: ')', fill: fill, size: P, dy: pdy });
  return out;
}
function radItems(r) {
