function coordText(c) { return '(' + compText(c[0]) + ', ' + compText(c[1]) + ')'; }

/* ---------- static base drawing ---------- */
UCPTS.forEach(function (p) {
  var q = ptXY(p.d);
  gBase.line(cx, cy, q[0], q[1]).stroke({ color: '#000', width: (p.d % 90 === 0) ? 1.5 : 1 });
});
gBase.circle(2 * Rr).center(cx, cy).fill('none').stroke({ color: '#000', width: 3 });
UCPTS.forEach(function (p) {
  var q = ptXY(p.d);
