}
arrowHead(1, 0); arrowHead(-1, 0); arrowHead(0, 1); arrowHead(0, -1);

/* ---------- labels ---------- */
var ucMode = 'All';
var OFF = 20;
function placeRow(row, ux, y, anchor) {
  var x;
  if (anchor === 'center') x = cx - row.w / 2;
  else if (anchor === 'left') x = cx + ux * (Rr + OFF);
  else x = cx + ux * (Rr + OFF) - row.w;
  x = Math.max(4, Math.min(x, UCW - 4 - row.w));
  row.g.attr('transform', 'translate(' + x + ',' + y + ')');
}
function itemsFor(degTxt, r, c, mode) {
  var it = [];
  if (mode === 'All' || mode === 'Degrees') it.push({ t: degTxt + '°', fill: UC_RED });
  if (mode === 'All') { it.push({ t: ',', fill: UC_RED }); it.push({ gap: 7 }); }
  if (mode === 'All' || mode === 'Radians') it = it.concat(radItems(r));
  if (mode === 'All') it.push({ gap: 12 });
  if (mode === 'All' || mode === 'Coordinates') it = it.concat(coordItems(c, UC_BLK, FS));
  return it;
}
function renderLabels(mode) {
  gLabels.clear();
  UCPTS.forEach(function (p) {
    var a = p.d * Math.PI / 180, ux = Math.cos(a), uy = Math.sin(a);
    if (p.d === 0) {
      if (mode === 'Coordinates') {
        placeRow(buildRow(itemsFor('0', p.r, p.c, mode), FS), ux, cy + 6, 'left');
      } else {
        placeRow(buildRow(itemsFor('0', p.r, p.c, mode), FS), ux, cy - 9, 'left');
