    .font({ family: UC_FAM, size: fsr }).fill(UC_BLUE).attr({ x: bx + 10, y: by + 37 });
  mkText(gRead, 'sin θ = y = ' + compText(p.c[1]) + '  ≈ ' + Math.sin(a).toFixed(3))
    .font({ family: UC_FAM, size: fsr }).fill(UC_GREEN).attr({ x: bx + 10, y: by + 55 });
